namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (TryValidateContext(principal, resource, request, out var decision))
            return decision;

        var administrator = principal!.Roles.Contains("administrator");
        var operatorRole = principal.Roles.Contains("operator");
        var auditor = principal.Roles.Contains("auditor");
        var owner = principal.Id == resource!.OwnerId;
        var delegated = delegations.HasDelegation(principal.Id, resource.Id, request!.Action);

        if (TryDecideBreakGlass(request, administrator, out decision))
            return decision;
        if (TryEnforceRestrictions(resource, request, administrator, out decision))
            return decision;
        if (TryAuthorizeAction(request, administrator, operatorRole, auditor, owner, delegated, out decision))
            return decision;

        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        return new AccessDecision(
            true,
            delegated ? "delegated" : "role-or-ownership",
            outsideBusinessHours || resource.Classification == "restricted");
    }

    private static bool TryValidateContext(
        Principal? principal,
        Resource? resource,
        AccessRequest? request,
        out AccessDecision decision)
    {
        if (principal is null || resource is null || request is null)
            return Deny("missing-context", true, out decision);
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
            return Deny("invalid-identity", true, out decision);
        if (principal.Suspended)
            return Deny("principal-suspended", true, out decision);
        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
            return Deny("tenant-mismatch", true, out decision);
        if (resource.Locked && request.Action != "read")
            return Deny("resource-locked", true, out decision);
        if (request.MinuteOfDay is < 0 or > 1439)
            return Deny("invalid-time", true, out decision);
        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
            return Deny("challenge-required", true, out decision);

        decision = default!;
        return false;
    }

    private static bool TryDecideBreakGlass(
        AccessRequest request,
        bool administrator,
        out AccessDecision decision)
    {
        if (!request.BreakGlass)
        {
            decision = default!;
            return false;
        }

        decision = !administrator || !request.StrongAuthentication
            ? new AccessDecision(false, "invalid-break-glass", true)
            : new AccessDecision(true, "break-glass", true);
        return true;
    }

    private static bool TryEnforceRestrictions(
        Resource resource,
        AccessRequest request,
        bool administrator,
        out AccessDecision decision)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
            return Deny("strong-authentication-required", true, out decision);
        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
            return Deny("trusted-network-required", true, out decision);
        if (request.Action == "delete" && !administrator)
            return Deny("administrator-required", true, out decision);

        decision = default!;
        return false;
    }

    private static bool TryAuthorizeAction(
        AccessRequest request,
        bool administrator,
        bool operatorRole,
        bool auditor,
        bool owner,
        bool delegated,
        out AccessDecision decision)
    {
        if (request.Action == "write" && !(administrator || operatorRole || owner || delegated))
            return Deny("write-not-authorised", true, out decision);
        if (request.Action == "read" && !(administrator || operatorRole || auditor || owner || delegated))
            return Deny("read-not-authorised", false, out decision);
        if (request.Action is not ("read" or "write" or "delete"))
            return Deny("unknown-action", true, out decision);

        decision = default!;
        return false;
    }

    private static bool Deny(string reason, bool auditRequired, out AccessDecision decision)
    {
        decision = new AccessDecision(false, reason, auditRequired);
        return true;
    }
}
